class Widget {};

// 1. Custom Deleters: `make` functions cannot be used
auto widgetDeleter = [](Widget* pw) {
    // Custom cleanup logic...
    delete pw;
};

// Must use direct `new` to specify a custom deleter
std::unique_ptr<Widget, decltype(widgetDeleter)> upw(new Widget(), widgetDeleter);
std::shared_ptr<Widget> spw(new Widget(), widgetDeleter);

// auto spw_fails = std::make_shared<Widget>(widgetDeleter); // Error: no such overload

// 2. Braced Initialization: `make` functions use parens, not braces

// This creates a vector with 10 elements, each with value 20
auto spv1 = std::make_shared<std::vector<int>>(10, 20);

// To create a vector with two elements {10, 20}, we need braced initialization.
// Must use direct `new` with an initializer list.
std::shared_ptr<std::vector<int>> spv2(new std::vector<int>{10, 20});
